// CreateMeterRequest is the request body of CreateMeter.
type CreateMeterRequest struct {
	Code string `json:"code"`
	// How a customer's events of a billing period combine into one quantity. SUM adds the quantities, COUNT counts
	// the events, MAX keeps the largest quantity. UNIQUE counts the distinct values of the event property named by
	// value_property (an event without the property is not counted; quantity_scale must be 0). LAST is the quantity
	// of the latest event of the period by event_time, ties broken by event id; an event that arrives after the
	// period's cutoff never changes it. A code cannot change into or out of UNIQUE or LAST in a later version. One
	// of: AGGREGATION_SUM, AGGREGATION_COUNT, AGGREGATION_MAX, AGGREGATION_UNIQUE, AGGREGATION_LAST.
	Aggregation string `json:"aggregation"`
	// Required for SUM, MAX and LAST (the event property holding the quantity) and for UNIQUE (the property whose
	// distinct values are counted)
	ValueProperty string                                   `json:"value_property,omitempty"`
	Filter        map[string]CreateMeterRequestFilterValue `json:"filter,omitempty"`
	// Decimal places, fixed per code
	QuantityScale *int `json:"quantity_scale,omitempty"`
	// Any unit of your choice: tokens, GB-h, seats, minutes
	UnitLabel string `json:"unit_label"`
	// Any group of your choice to file the meter under (compute, storage, AI); changes nothing in metering or
	// billing
	Category string `json:"category,omitempty"`
}

// CreateMeterRequestFilterValue is an object of the API; see components.schemas.CreateMeterRequestFilterValue
// in api/openapi/v1.yaml.
type CreateMeterRequestFilterValue struct {
	Values []string `json:"values,omitempty"`
}

// CreatePaymentLinkRequest is the request body of CreatePaymentLink.
type CreatePaymentLinkRequest struct {
	// Default: invoice when invoice_id is set, credit_pack when pack_id is set, else adhoc. One of: invoice, adhoc,
	// credit_pack.
	Kind      string `json:"kind,omitempty"`
	InvoiceID string `json:"invoice_id,omitempty"`
	// credit_pack: the active credit pack to sell. Its price and currency become the link's amount; they are never
	// taken from the request
	PackID string `json:"pack_id,omitempty"`
	// credit_pack: how many packs one payment buys (default 1)
	Quantity *int `json:"quantity,omitempty"`
	// adhoc: a positive int64 in minor units (a string or a number)
	AmountMinor *Int64 `json:"amount_minor,omitempty"`
	// adhoc: ISO 4217; the tenant's currency when empty
	Currency string `json:"currency,omitempty"`
	// adhoc: what it is for; printed on the invoice
	Description string `json:"description,omitempty"`
	// adhoc: make the invoice out to this customer. credit_pack: required, the customer who receives the credits
	CustomerExternalID string `json:"customer_external_id,omitempty"`
	// Default true for adhoc, false for invoice
	SingleUse *bool `json:"single_use,omitempty"`
	// adhoc and credit_pack, optional: a promotion code the payer gets without typing it (a one-off invoice with a
	// discount). Checked against the link's own amount now (a coupon.* error if it does not work); claimed when the
	// payer continues. An invoice that exists is not changed, so a kind invoice link takes none
	PromotionCode string `json:"promotion_code,omitempty"`
	// Optional: the agreements the payer must accept on this link's page. The list replaces the seller's
	// tenant-wide required_kinds for this link (it does not add to it); empty or absent: the setting applies. The
	// texts must be published before the link is used, or the page offers no way to pay. An ad-hoc link hands its
	// list to the invoice link the payer continues on. 400 billing.payment_link.bad_required_contracts for an
	// unknown kind or one named twice
	RequiredContracts []string `json:"required_contracts,omitempty"`
	// Default 30 for adhoc, 90 for invoice
	ExpiresInDays  *int   `json:"expires_in_days,omitempty"`
	IdempotencyKey string `json:"idempotency_key,omitempty"`
}

