// Dispute is an object of the API; see components.schemas.Dispute in api/openapi/v1.yaml.
type Dispute struct {
	// Payrudder's id of the case
	ID       string `json:"id"`
	Provider string `json:"provider"`
	// The provider's reference of the case (Stripe's du_..., Paddle's cb_ or cbw_ and the transaction)
	DisputeID string `json:"dispute_id"`
	// The payment that is disputed, as the provider calls it (a Stripe PaymentIntent id, a Paddle transaction id)
	PaymentRef string `json:"payment_ref"`
	// The invoice of that payment; absent for a payment Payrudder did not make
	InvoiceID string `json:"invoice_id,omitempty"`
	// The disputed amount
	AmountMinor Int64  `json:"amount_minor"`
	Currency    string `json:"currency"`
	// One of: open, won, lost.
	Outcome string `json:"outcome"`
	// A chargeback proper, which takes the money back; false is an inquiry or a warning ahead of one
	Formal bool `json:"formal"`
	// The provider's own word (Stripe's needs_response, under_review, won, lost, warning_closed ...)
	ProviderStatus string `json:"provider_status"`
	// The cardholder's reason in the provider's words (Stripe's fraudulent, product_not_received ...); absent when
	// the provider does not say
	Reason string `json:"reason,omitempty"`
	// When your evidence is due; absent when the provider does not say
	EvidenceDueTime time.Time `json:"evidence_due_time,omitempty"`
	OpenedTime      time.Time `json:"opened_time"`
	// Absent while the case is open
	ClosedTime time.Time `json:"closed_time,omitempty"`
	// What the provider took for the case, when a notification said (in `fee_currency`, which is the currency the
	// provider settles in and can differ from `currency`). It is also a row of the payment ledger of its own.
	// Stripe's is read from the balance transactions of the dispute and Paddle's from the chargeback fee of the
	// payout totals; UNVERIFIED against a live account. Absent when no notification named a fee
	FeeMinor Int64 `json:"fee_minor,omitempty"`
	// The currency of `fee_minor`
	FeeCurrency string `json:"fee_currency,omitempty"`
	// Your own mark that you dealt with the case (`PUT /v1/disputes/{id}/handled`). It changes nothing at the
	// provider
	Handled bool `json:"handled"`
	// Absent when the case is not marked
	HandledTime time.Time `json:"handled_time,omitempty"`
	// Who marked it; absent when it is not marked, for a viewer of the account, and for an API key that holds no
	// audit:read (the read_only and billing roles)
	HandledBy string `json:"handled_by,omitempty"`
	// How many notes you wrote (`GET /v1/disputes/{id}/history`)
	NoteCount Int64 `json:"note_count"`
}

// DisputeEvent is an object of the API; see components.schemas.DisputeEvent in api/openapi/v1.yaml.
